  public function executeOnPublish()
  {
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');	
    if(!$this->tienePrivilegio('CARTELERA_DESPUBLICAR_REGISTRO')){
      return http_response_code(400);
    }
    //******************************************************************************************
    $cartelera_informativa = CarteleraInformativaPeer::retrieveByPK($this->getRequestParameter('cartelerainformativa_id'));
    $cinformativo_anterior = $cartelera_informativa->copy();
    //******************************************************************************************
    $estadopublicacion_id = $cartelera_informativa->getEstadopublicacionId() == 1 ? StatusPublicacion::Despublicado : StatusPublicacion::Publicado;
    $cartelera_informativa->setEstadopublicacionId($estadopublicacion_id);
    $cartelera_informativa->save();
    //******************************************************************************************
    AuditLogPeer::guardarAuditoriaLite(CarteleraInformativaPeer::getOMClass(),$cinformativo_anterior,$cartelera_informativa,
      ModulesEnable::CarteleraInformativa,$cartelera_informativa->getPrimaryKey(),$usuariologuiado);
    //******************************************************************************************
    $this->cartelera_informativa = $cartelera_informativa;
    $this->forward404Unless($cartelera_informativa);
  }

